# S463a gloss decisions. Read by content, card by card, old verse vs live verse.
# FITS: gloss still describes the live verse at the card's address — no change.
# MOVE: (addr) the gloss describes the live verse at addr (the old text was that verse under a wrong number); the note's
#        "Enoch old-addr" references are patched to the new addr. Optional third item: replacement prose.
# REWRITE: (prose) same address; the prose after the canon quote is replaced.
# Q: put to Yoshi.
D = {}
def FITS(*ids):
    for i in ids: D[i]=('FITS',)
def MOVE(addr,*ids,prose=None):
    for i in ids: D[i]=('MOVE',addr,prose)
def REWRITE(i,prose): D[i]=('REWRITE',prose)
def Q(i,why): D[i]=('Q',why)

